var navigation=document.querySelector('nav'),toggle=navigation.querySelector('.menu-toggle');
function closeMenu(){navigation.removeAttribute('data-open');toggle.setAttribute('aria-expanded','false')}
toggle.addEventListener('click',function(){var open=toggle.getAttribute('aria-expanded')!=='true';navigation.dataset.open=String(open);toggle.setAttribute('aria-expanded',String(open))});
